using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using OpenAI;

// Build configuration
var configuration = new ConfigurationBuilder()
    .AddJsonFile("appsettings.json", optional: true)
    .AddEnvironmentVariables()
    .Build();

var apiKey = configuration["AI:ApiKey"]
    ?? throw new InvalidOperationException(
        "Set the AI:ApiKey configuration value (or AI__ApiKey environment variable) to your OpenAI API key.");

var modelId = configuration["AI:Model"] ?? "gpt-4o-mini-2024-07-18";

// Build services
var services = new ServiceCollection();
services.AddLogging();
services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAIClientOptions(), new System.ClientModel.ApiKeyCredential(apiKey)));

var serviceProvider = services.BuildServiceProvider();
var chatClient = serviceProvider.GetRequiredService<IChatClient>();

// Define tools
var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearch),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
};

// Create the research agent
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic, you:
        1. Search the web for relevant information using the web_search tool (perform multiple searches with different queries to get broad coverage).
        2. Save important findings as notes using the save_note tool.
        3. After gathering enough information, retrieve all notes with get_notes and produce a clear, well-structured summary of your findings.
        Always cite your sources. Be thorough but concise.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

// Wrap in a loop agent with iteration limits
var loopAgent = new LoopAgent(
    agent,
    new CompletionMarkerLoopEvaluator(),
    new LoopAgentOptions { MaxIterations = 10 });

// Get the research topic
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");
Console.WriteLine(new string('-', 60));

// Run the agent
var response = await loopAgent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}");

Console.WriteLine(response.Text);

// --- Tool implementations ---

var notes = new List<string>();

[Description("Searches the web for information on a given query. Returns search results with titles, snippets, and URLs.")]
static string WebSearch([Description("The search query to look up")] string query)
{
    // Simulated web search results for demonstration purposes.
    // In production, replace with a real search API (e.g., Bing Search API).
    return $"""
        Search results for: "{query}"

        1. Title: "{query}" - Wikipedia
           URL: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}
           Snippet: This article provides a comprehensive overview of {query}, including its history, key concepts, and current developments.

        2. Title: Understanding {query} - A Complete Guide
           URL: https://example.com/guide/{Uri.EscapeDataString(query)}
           Snippet: An in-depth guide covering the fundamentals of {query}, recent advancements, and practical applications.

        3. Title: Latest Research on {query}
           URL: https://research.example.com/{Uri.EscapeDataString(query)}
           Snippet: Recent peer-reviewed studies explore new findings related to {query}, revealing important trends and implications.
        """;
}

[Description("Saves a research note for later reference. Use this to record important findings during research.")]
string SaveNote(
    [Description("A title or label for the note")] string title,
    [Description("The content of the note")] string content)
{
    var note = $"[{title}]: {content}";
    notes.Add(note);
    return $"Note saved: '{title}' ({notes.Count} total notes)";
}

[Description("Retrieves all saved research notes. Use this to review gathered information before writing a summary.")]
string GetNotes()
{
    if (notes.Count == 0)
    {
        return "No notes saved yet.";
    }

    return $"Saved notes ({notes.Count}):\n" + string.Join("\n\n", notes.Select((n, i) => $"{i + 1}. {n}"));
}

